-- Логотипи сутностей (продукт, клієнт, стартап): значок замість першої літери; файл — у `files`.
CREATE TABLE logos (
  kind TEXT NOT NULL,              -- product | client | startup
  ref_id INTEGER NOT NULL,
  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (kind, ref_id)
);
INSERT INTO changelog (title, body, created_at) VALUES ('Логотипи і блоки замість полів', 'У продуктів і клієнтів тепер значок-логотип: наведи на значок → «⋯» → «Завантажити логотип» (PNG/SVG/JPG до 5 МБ) або «Прибрати». Логотип видно в шапці, у списках і в лівій панелі клієнта. Без логотипу — кольоровий значок з першою літерою. Продукт → «Змінити» більше не стіна полів: кожен розділ (що це, як працює, фічі, склад, посилання, плюси, мінуси, наступний крок) — окремий блок з текстом або списком, клік — правка в попапі.', datetime('now'));

INSERT INTO changelog (title, body, created_at) VALUES ('Креативи клієнта простіше', 'Три кроки тепер — компактні плитки: «Контекст клієнта» (Скопіювати / Налаштувати — оффер, стиль, правила блоками з правкою в попапі), «Промпт креативу» (+ Новий промпт у вікні, готовий промпт одразу з кнопкою «Скопіювати»; поруч — копіювати останній CR-N), «Результат назад» (вставка відповіді Claude у вікні). «Хто ми» перейменовано на «Контекст клієнта». Попапи з правкою самі закриваються після «Зберегти».', datetime('now'));
